    title: "以太王冠", intro: "这一生中找到的七块王冠碎片。王冠箍环最多可镶嵌三块碎片并获得其加成；心之碎片苏醒后始终生效。飞升会失去碎片，但你选择的结局加成会伴随每一世。", count: "{n}/{total}块碎片", circlet: "王冠箍环", circletHint: "最多镶嵌三块碎片。只有已镶嵌的碎片才会提供加成并能发动其力量。", socketEmpty: "空槽", heart: "心之碎片", heartAsleep: "仍未苏醒", notFound: "尚未找到", where: "位置：{hint}", passive: "镶嵌时生效", power: "力量", setToUse: "将碎片镶入王冠箍环即可使用其力量", use: "召唤力量", readyIn: "{time}后就绪", activeFor: "生效中 · {time}", setIn: "镶嵌", takeOut: "取下", found: "找到王冠碎片：{shard}！", foundPlain: "王冠碎片：{shard}", foundHint: "可在王冠界面查看。", powerUsed: "已召唤{power}", choiceTitle: "抉择", choiceIntro: "王冠已然完整。将它交给某人，或不交给任何人。这一世的故事将在此落幕，而结局带来的加成会伴随你往后的每一世。", choiceLocked: "在同一世中集齐全部七块碎片并击败以太君主，即可作出抉择。", confirmTitle: "选择这个结局？", confirmMessage: "{ending}：{desc} 结局加成会伴随你往后的每一世。此生一旦选择便无法撤回。", confirm: "选择", chosenNow: "此生已选择", chosenBefore: "前世已选择", endingToast: "结局：{ending}", legacyTitle: "传承", legacyIntro: "你选择过的结局加成将保留在往后的每一世。", legacyNone: "尚未选择结局。每一世都可以选择一个新结局。",
    shards: {
      forge: { name: "熔炉碎片", desc: "由铁砧公会秘密保管。它仍记得铁锤的声音。" },
      sap: { name: "树液碎片", desc: "来自蛇神神殿，是生命本身的核心。万物在它附近都会生长。" },
      sea: { name: "海洋碎片", desc: "与海妖一同从深海取得。它带着盐与风暴的气息。" },
      winter: { name: "寒冬碎片", desc: "冬之女王的赠礼，寒冷得足以令铁石碎裂。" },
      flame: { name: "烈焰碎片", desc: "来自青铜巨龙的宝藏，光芒耀眼得令人无法直视。" },
      deep: { name: "深渊碎片", desc: "在世界尽头、坠落的光芒汇聚之处发现。" },
      heart: { name: "心之碎片", desc: "王冠碎裂时坠入你体内的碎片。面对国王时，它便会苏醒。" },
    },
    hints: { forge: "锻造达到40级", sap: "击败大娜迦", sea: "击败海妖", winter: "击败冬之女王", flame: "击败青铜巨龙", deep: "在此生中击败远古巨龙，并在深渊击败200只生物", heart: "击败虚空帝皇" },
