    creatures: { gilded_goblin: "镀金哥布林", gilded_goblinDesc: "很难命中，也没有威胁，却随身带着巨额财富。征兆结束时它就会逃走。", rift_horror: "裂隙怪物", rift_horrorDesc: "它会变得和你一样强。每只都有可能掉落遗物。" },
