  bestiary: {
    loreLocked: "研究这种生物以了解它的故事。",
    lore: {
      chicken: "黎明草原的母鸡会下出蛋黄如金的鸡蛋。{keeper}坚称这和土壤有关，而那片土地从未受到裂变的侵蚀。",
      goblin: "哥布林喜欢闪亮的东西。自从王冠碎裂后，它们能喜欢的闪亮物件就多了不少。",
      cow: "温顺、固执，也是金酒杯酒馆能做出王国最好奶酪的秘诀。",
      rat: "暗影森林的老鼠在旧王家营地筑巢，啃咬一切仍带着国王气息的东西。",
      wolf: "牧羊人说，狼群对着尖塔而非月亮嚎叫。天朗气清时，你就会明白他们的意思。",
      bandit: "大多数强盗在歉收前都是农夫。即便如此，天黑后他们也不肯走古道。",
      skeleton: "在铁之洞窟待得太久的矿工。熔炉仍让他们忙个不停。",
      golem: "王冠时代留下的熔炉工具，至今还在把矿石送往一座三百年来无人使用的铁砧。",
      troll: "巨魔会舔洞窟的墙壁，尝尝以太矿的味道。这让它们力大无穷，也脾气暴躁得很。",
      snake: "沼泽里的蛇每年都长得更长。树液碎片滋养着这里的一切，不管它们是否该长成这样。",
      scorpion: "蝎壳坚硬如铁。草药师说，毒液煮得恰到好处能退烧；煮错了，你也会一命呜呼。",
      werewolf: "他们曾是猎人，喝下了泥沼的温泉水。每逢月圆，月亮都会提醒他们发生过什么。",
      specter: "王室卫兵为守护高曦城而死，至今仍在等待撤退的命令。",
      vampire: "旧宫廷里的贵族不愿在国王死后老去。他们如愿以偿了。",
      gargoyle: "它们原本被雕刻出来守望王都。城池沦陷后，它们仍在守望。如今，它们看着你。",
      bear: "冰封山峰的熊会在漫长冬季中沉睡。寒冬碎片坠落后，冬季就再也没有结束。",
      ice_golem: "冬之女王用积雪塑成它们，守卫冰封王国。它们不知道那个王国早已不复存在。",
      ogre: "雪地食人魔只拿恐惧和冻鱼做买卖。令人意外的是，这两样它们都很在行。",
      green_dragon: "幼龙饮用烈焰碎片的力量。每喝一口，它们的寿命就增加百年，脾气也更坏几分。",
      red_dragon: "年迈的红龙绝不会忘记侮辱或金币。想从它手里抢走这两样的人，大多会化作灰烬，让它记忆深刻。",
      wyvern: "双足飞龙守着通往巨龙巢穴的道路。它们行动迅速、饥肠辘辘，也不接受谈判。",
      minotaur: "传送门另一侧的道路扭曲成迷宫。牛头人就诞生在那里，熟悉每一个错误的岔路。",
      hydra: "它是泥沼九头蛇的近亲，却被深渊扭曲成伤口还没流完血便能长出新头的怪物。",
      demon: "深渊恶魔曾经并非如此。它们原本是什么，裂隙已经忘了，它们自己也忘了。",
      void_stalker: "它靠你体内的光追猎。你越明亮，它找到你的速度就越快。",
      star_wraith: "这是坠入虚空裂隙的星辰残骸。它仍在燃烧，只是火焰冰冷。",
      abyssal_titan: "裂隙最古老的守护者。国王坠落前它便已存在，也记得国王当时发出的声音。",
      seraph: "天穹尖塔的守护者曾侍奉光明。天眼开启后，它们一个接一个地堕落了。",
      astral_golem: "它由星光铸成，负责将王冠运上尖塔。它的使命早已完成，却没人告诉它。",
      elder_wyrm: "世上最古老的巨龙栖居云端。王冠铸成时，它就已经年迈。",
      warren_chief: "哥布林酋长把一片王冠碎片挂在脖子上，自称国王。倒也不能说他完全不对。",
      skeleton_king: "一位王室管家将自己封在地穴里，与主人的宝藏一同埋葬。直到现在，他还在清点财宝。",
      naga: "蛇神神殿最后一位女祭司。她曾祈求永生，某个极其古老的存在回应了她。",
      winter_queen: "她冰封了自己的王国，只为让一切永不改变。她如愿了，就连悲伤也不曾消退。",
      bronze_wyrm: "第一任国王的巨龙。它至今仍守着宝藏，早已忘记自己为何而守。",
      rift_warden: "它屹立于虚空圣所中心，不让任何东西出去。有人说，它是在阻止某物进来。",
      goblin_king: "哥布林之王坐在一堆偷来的锅子上统治臣民。它的王冠是锡做的，它对此非常介意。",
      troll_lord: "巨魔领主一口气吞下了一整条以太矿脉，从此就没有停止过生长。",
      kraken: "海洋碎片坠入深海时，它随之苏醒。水手每次出海都会留下第一条鱼供奉它，以防万一。",
      necromancer: "他曾侍奉莫温，如今依然如此。他造成的每一场死亡，她都能听见。",
      ancient_dragon: "它见证了王冠铸成，也目睹它碎裂。从那以后，它一直等待着一个值得交谈的人。",
      void_emperor: "有人说，它趁无人注视时会显露{king}的面容；也有人说，它就是他仅存的一切。",
      aether_sovereign: "尖塔之巅，有某种存在戴着纯光铸成的王冠。抵达那里的人，从未说出那张面孔属于谁。",
    },
    intro: "你击败的每种生物都会记录在这里。继续狩猎以了解它的掉落物；精通后，对它造成的命中率和伤害提高{pct}%。研究完一组中的所有生物，即可领取奖励。", tiers: { seen: "已遭遇", studied: "已研究", hunted: "已精通" }, tierHints: { seen: "属性与弱点", studied: "全部掉落物及其概率", hunted: "命中率与伤害提高{pct}%" }, reward: "奖励", complete: "此组中的所有生物均已研究。", claim: "领取奖励", claimed: "已领取图鉴奖励：<b>{group}</b>", kills: "已击败{n}次", unknown: "尚未遭遇", vsThis: "对其", undiscovered: "未发现的掉落物", next: "下一阶段：{tier}", groups: { dungeons: "地城首领", bosses: "世界首领" },
  },
