      startMining: { title: "开始采矿", text: "点击<b>铜矿</b>或<b>锡矿</b>。行动会自动重复，直到你手动停止。" },
      gatherOre: { title: "采集矿石", text: "让英雄采一会儿矿。每次行动都会获得经验、矿石和对应矿物的精通经验。" },
      openSmithing: { title: "打开锻造界面", text: "采集技能会为工匠技能提供原料。打开<b>锻造</b>，把矿石熔成金属锭。" },
      smeltBar: { title: "熔炼青铜锭", text: "一块<b>青铜锭</b>需要一份铜矿和一份锡矿。缺少材料时，英雄会先去采集。" },
      openInventory: { title: "查看背包", text: "制作的物品都会存放在这里。点击物品即可装备、出售或查看用途。" },
      openCombat: { title: "打开地图", text: "选择一个区域和狩猎地点。战斗可以训练攻击、力量、防御和生命值；怪物会掉落金币与战利品。" },
      startFight: { title: "开始战斗", text: "先去<b>黎明草原</b>挑战较弱的敌人，例如鸡。食物已在<b>补给</b>中设好，受伤时英雄会自动进食。" },
      winFights: { title: "赢得三场战斗", text: "战斗会自动进行。每次攻击都会积攒<b>能量</b>，能量足够时英雄会自动施放招式。" },
      openHero: { title: "了解你的英雄", text: "升级会获得英雄经验、属性点和天赋点。在此分配点数并更换装备。" },
      openQuests: { title: "查看任务板", text: "任务会解锁新区域和首领，每日任务也会提供奖励。" },
      openTavern: { title: "拜访酒馆", text: "雇用员工替你训练技能，离线时也会继续工作。酒馆老板还会透露与你故事有关的消息。" },
      openJournal: { title: "打开日志", text: "你的故事记录在<b>日志</b>中，探索时会解锁新篇章。若你愿意，还剩三个小目标。" },
      openGuilds: { title: "拜访公会", text: "王国各地有十几个<b>公会</b>相互竞争。找一个适合你职业的公会，通过试炼并接受委托。" },
      openFarming: { title: "看看你的农场", text: "<b>农耕</b>即使在你离线时也会持续生长。妥善照料农田，利用堆肥、季节、杂交作物和农场院落提升收成。" },
      openCompendium: { title: "打开图鉴", text: "<b>图鉴</b>会记录每种生物、物品和杰作，每完成一页还能领取奖励。入门指引到此结束！" },
