    bosses: {
      colossus: { name: "巨石巨像", desc: "旧王逝去时苏醒的行走山岳。刀剑在它身上折断，法术却能使它崩裂。" },
      hydra: { name: "泥沼九头蛇", desc: "砍掉一颗头就会长出两颗。只有近身挥舞的钢铁才能跟上它的再生速度。" },
      lich_queen: { name: "莫温，巫妖女王", desc: "她统治了千年，还不打算停下。她的亡者依然听命于她。" },
      ashen_wyrm: { name: "灰烬巨龙", desc: "一条灰烬化作的巨龙。魔法在它的热浪中消散，鳞甲却挡不住刀刃。" },
      leviathan: { name: "利维坦", desc: "它从深海升起，鳞片能将攻击尽数反弹。要从远处出手。" },
      rimeheart: { name: "霜心巨人", desc: "由活冰构成的巨人。箭矢会在它身上碎裂，寒气则令四肢迟缓。" },
    },
