    riddles: { shadow: "我整天跟着你，夜里却消失不见。我是什么？", echo: "我没有嘴却能说话，无人询问也会作答。我是什么？", map: "我有城市却没有房屋，有森林却没有树木，有河流却没有水。我是什么？", candle: "我站得越久，身子就越短。我是什么？", key: "我有牙齿却从不咬人，还能打开紧锁之物。我是什么？", silence: "只要说出我的名字，我便消失。我是什么？", time: "我能愈合伤口，也能磨平高山，却无人能握住我。我是什么？", footsteps: "你留下的越多，我也留下得越多。我是什么？", river: "我奔流却不会走路，有嘴却不吃饭，有河床却不睡觉。我是什么？", anvil: "我每天挨打却从不还手，最好的刀刃却在我身上诞生。我是什么？", egg: "必须先打破我才能使用。我是什么？", secret: "只要说出去，我便不再属于你。我是什么？", moon: "我每晚变换面容，却从未离开天空。我是什么？", fire: "喂我食物我便活着，给我水喝我就死去。我是什么？", name: "我属于你，但别人用我的次数远胜于你。我是什么？", arrow: "我无翼也能飞，无手也能击中目标，是弓送我上路。我是什么？" },
